#tc-card {
  position: absolute; left: 50%; top: 50%;
  display: flex; align-items: center; gap: 18px;
  padding: 16px 26px 18px 18px;
  border-width: 4px;
  box-shadow: inset 3px 3px 0 rgba(255,255,255,0.18), inset -3px -3px 0 rgba(0,0,0,0.4), 9px 10px 0 0 var(--accent), 9px 10px 0 4px #000;
}
#tc-clock { position: relative; width: 60px; height: 60px; flex: 0 0 60px; }
/* pixel clock face: stepped square ring built from box-shadows */
#tc-face {
  position: absolute; inset: 0;
  background: var(--gold);
  clip-path: polygon(30% 0, 70% 0, 70% 10%, 85% 10%, 85% 20%, 92% 20%, 92% 30%, 100% 30%, 100% 70%, 92% 70%, 92% 80%, 85% 80%, 85% 90%, 70% 90%, 70% 100%, 30% 100%, 30% 90%, 15% 90%, 15% 80%, 8% 80%, 8% 70%, 0 70%, 0 30%, 8% 30%, 8% 20%, 15% 20%, 15% 10%, 30% 10%);
  box-shadow: inset -6px -6px 0 rgba(0,0,0,0.25), inset 6px 6px 0 rgba(255,255,255,0.35);
}
.tc-hand { position: absolute; left: 27px; width: 6px; background: var(--ink); transform-origin: 50% 100%; }
#tc-hand-m { top: 9px; height: 21px; }
#tc-hand-h { top: 16px; height: 14px; }
#tc-pin { position: absolute; left: 25px; top: 25px; width: 10px; height: 10px; background: var(--redstone); border: 2px solid var(--ink); }
#tc-text { color: var(--accent); line-height: 1.05; text-align: left; }
.mc-v #tc-text { text-align: center; }
.mc-v #tc-card { flex-direction: column; gap: 12px; padding: 20px 22px 22px; }
=== templates/time_card/template.js
MC.define(function (S) {
  var v = S.v, d = S.d;
  var text = String(v.text || "3 HOURS LATER").toUpperCase();
  var el = document.getElementById("tc-text");
  var fit = MC.fit(text, d.vertical
    ? { maxWidth: 430, maxSize: 84, minSize: 26, k: 0.53, maxLines: 3, maxHeight: 280 }
    : { maxWidth: 640, maxSize: 86, minSize: 26, k: 0.53, maxLines: 2, maxHeight: 190 });
  el.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(el, fit.lines);

  var tl = gsap.timeline({ paused: true });
  var card = "#tc-card";
  // stamp in
  tl.fromTo(card, { xPercent: -50, yPercent: -50, scale: 0, rotation: -14 },
    { xPercent: -50, yPercent: -50, scale: 1, rotation: -3, duration: 0.32, ease: "back.out(2.4)" }, 0);
  tl.fromTo("#tc-clock", { scale: 0, rotation: -90 }, { scale: 1, rotation: 0, duration: 0.3, ease: "back.out(3)" }, 0.1);
  tl.fromTo(parts.words, { y: 26, scale: 0.3, opacity: 0 },
    { y: 0, scale: 1, opacity: 1, duration: 0.24, ease: "back.out(3)", stagger: 0.07 }, 0.16);
  // clock: minute hand spins in hard steps (time passing), hour hand creeps
  tl.fromTo("#tc-hand-m", { rotation: 0 }, { rotation: 720, duration: 1.15, ease: "steps(16)" }, 0.2);
  tl.fromTo("#tc-hand-h", { rotation: 90 }, { rotation: 180, duration: 1.15, ease: "steps(4)" }, 0.2);
  // small settle bump
  tl.to(card, { scale: 1.06, duration: 0.08, ease: "power2.out" }, 0.9);
  tl.to(card, { scale: 1, duration: 0.14, ease: "back.out(3)" }, 0.98);
  // exit
  tl.to(parts.words, { y: -16, opacity: 0, duration: 0.14, ease: "power2.in", stagger: 0.03 }, d.duration - 0.36);
  tl.to(card, { scale: 0, rotation: 10, duration: 0.24, ease: "back.in(2.2)" }, d.duration - 0.26);
  return tl;
});
