=== templates/counter/template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(99);
  var from = MC.num(v.from, 0), to = MC.num(v.to, 100);
  var prefix = String(v.prefix || ""), suffix = String(v.suffix || "");
  var label = String(v.label || "").toUpperCase();
  function fmt(x) { return prefix + String(Math.round(x)) + suffix; }

  var K = 0.56;
  var maxChars = Math.max(fmt(from).length, fmt(to).length, 2);
  var numSize = Math.floor(Math.min(d.vertical ? 150 : 124, (W * (d.vertical ? 0.74 : 0.5)) / (maxChars * K)));
  var boxW = Math.round(maxChars * numSize * K + numSize * 0.9);
  var boxH = Math.round(numSize * 1.5);
  var box = document.getElementById("ct-box");
  box.style.width = boxW + "px"; box.style.height = boxH + "px";
  box.style.left = ((W - boxW) / 2) + "px";
  box.style.top = (H * (d.vertical ? 0.38 : 0.42) - boxH / 2) + "px";

  var num = document.getElementById("ct-num");
  num.style.fontSize = numSize + "px";
  num.style.top = ((boxH - numSize) / 2 + numSize * 0.04) + "px";
  num.textContent = fmt(from);

  var lab = document.getElementById("ct-label");
  var labSize = Math.floor(Math.min(d.vertical ? 34 : 30, (boxW * 0.9) / (Math.max(label.length, 1) * 0.53)));
  lab.textContent = label;
  lab.style.fontSize = labSize + "px";
  lab.style.padding = Math.round(labSize * 0.25) + "px " + Math.round(labSize * 0.4) + "px " + Math.round(labSize * 0.08) + "px";
  lab.style.left = "-14px";
  lab.style.top = (-labSize - 16) + "px";
  if (!label) lab.style.display = "none";

  var bitsWrap = document.getElementById("ct-bits"), bits = [];
  for (var i = 0; i < 12; i++) {
    var b = document.createElement("div");
    b.className = "ct-bit";
    b.style.left = (boxW / 2 - 6) + "px"; b.style.top = (boxH / 2 - 6) + "px";
    b.style.background = i % 2 ? "var(--accent)" : "var(--paper)";
    bitsWrap.appendChild(b);
    var a = (i / 12) * Math.PI * 2 + rnd() * 0.3;
    bits.push({ el: b, x: Math.cos(a) * (boxW * 0.55 + rnd() * 50), y: Math.sin(a) * (boxH * 0.7 + rnd() * 40) });
  }

  var tl = gsap.timeline({ paused: true });
  tl.set(bits.map(function (b) { return b.el; }), { opacity: 0 }, 0);
  tl.fromTo(box, { scale: 0, rotation: -10 }, { scale: 1, rotation: -2, duration: 0.3, ease: "back.out(2.4)" }, 0);
  tl.fromTo(lab, { y: 30, scale: 0.3, opacity: 0 }, { y: 0, scale: 1, opacity: 1, duration: 0.26, ease: "back.out(3)" }, 0.12);

  // the tick: a proxy value drives the text (seek-safe: text is a pure function of tween progress)
  var T0 = 0.24, TD = 1.15;
  var proxy = { v: from };
  tl.fromTo(proxy, { v: from }, {
    v: to, duration: TD, ease: "power2.inOut",
    onUpdate: function () { num.textContent = fmt(proxy.v); }
  }, T0);
  // ticking jitter while counting (finite repeats)
  tl.fromTo(num, { scale: 1 }, { scale: 1.05, duration: 0.07, ease: "steps(1)", yoyo: true, repeat: Math.max(0, Math.floor(TD / 0.07) - 1) }, T0);
  // land: punch + accent flash + burst
  var LAND = T0 + TD;
  tl.fromTo(num, { scale: 1.32 }, { scale: 1, duration: 0.3, ease: "back.out(3)", immediateRender: false }, LAND);
  tl.fromTo(num, { color: MC.css("--paper") || "#F4F1E8" }, { color: String(v.accent || "#4FE0D6"), duration: 0.05, immediateRender: false }, LAND);
  tl.fromTo(box, { rotation: -2 }, { keyframes: [{ rotation: 3 }, { rotation: -2 }], duration: 0.24, ease: "power1.inOut", immediateRender: false }, LAND);
  bits.forEach(function (b) {
    tl.fromTo(b.el, { x: 0, y: 0, opacity: 1, scale: 1, rotation: 0 },
      { x: b.x, y: b.y, opacity: 0, scale: 0.4, rotation: 180, duration: 0.45, ease: "power2.out", immediateRender: false }, LAND);
  });
  // exit
  tl.to(box, { scale: 0, rotation: 8, duration: 0.22, ease: "back.in(2)" }, d.duration - 0.24);
  return tl;
});
