/* Shared Minecraft-flavoured primitives for every motion template.
   Colours/fonts come from brand.css (generated from studio/brand/brand.json by mcstudio.motion).
   Templates are authored on a half-res logical canvas (960x540 / 540x960);
   full renders supersample x2 to 1920x1080 / 1080x1920. */

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { margin: 0; overflow: hidden; background: transparent; }

.mc-root { position: relative; overflow: hidden; }
.mc-stage { position: absolute; inset: 0; }

/* Opaque mode (render on brand ink, for card segments). Fill lives on a child, never the root. */
.mc-bgfill {
  position: absolute; inset: 0; opacity: 0;
  background-color: var(--ink);
  background-image:
    linear-gradient(rgba(255,255,255,0.035) 2px, transparent 2px),
    linear-gradient(90deg, rgba(255,255,255,0.035) 2px, transparent 2px);
  background-size: 40px 40px;
}
.mc-opaque .mc-bgfill { opacity: 1; }

/* Fonts */
.f-display { font-family: "MC Ten", "Minecraft", monospace; font-weight: normal; }
.f-caption { font-family: "Luckiest Guy", "MC Ten", sans-serif; font-weight: normal; }
.f-ui      { font-family: "Minecraft", monospace; font-weight: normal; }
.f-ui-bold { font-family: "Minecraft Bold", "Minecraft", monospace; font-weight: normal; }

/* Chunky blocky outline: 8 hard offsets + a pixel drop shadow. Scales with font-size. */
.mc-outline {
  --ol: var(--ink);
  text-shadow:
    0.07em 0 0 var(--ol), -0.07em 0 0 var(--ol), 0 0.07em 0 var(--ol), 0 -0.07em 0 var(--ol),
    0.07em 0.07em 0 var(--ol), -0.07em 0.07em 0 var(--ol), 0.07em -0.07em 0 var(--ol), -0.07em -0.07em 0 var(--ol),
    0.07em 0.16em 0 var(--ol), 0 0.16em 0 var(--ol), -0.07em 0.16em 0 var(--ol);
}
.mc-outline-thin {
  --ol: var(--ink);
  text-shadow:
    0.05em 0 0 var(--ol), -0.05em 0 0 var(--ol), 0 0.05em 0 var(--ol), 0 -0.05em 0 var(--ol),
    0.05em 0.05em 0 var(--ol), -0.05em 0.05em 0 var(--ol), 0.05em -0.05em 0 var(--ol), -0.05em -0.05em 0 var(--ol),
    0 0.11em 0 var(--ol);
}

/* Minecraft GUI bevel panel */
.mc-panel {
  --pc: var(--ink);
  background: var(--pc);
  border: 3px solid #000;
  box-shadow:
    inset 3px 3px 0 rgba(255,255,255,0.22),
    inset -3px -3px 0 rgba(0,0,0,0.38),
    5px 6px 0 0 rgba(0,0,0,0.45);
}

/* A single beveled "block" cube face */
.mc-block {
  position: absolute;
  background: var(--bc, var(--grass));
  border: 2px solid #000;
  box-shadow:
    inset 4px 4px 0 rgba(255,255,255,0.28),
    inset -4px -4px 0 rgba(0,0,0,0.32);
}
.mc-block::after { /* pixel speckle */
  content: ""; position: absolute; width: 22%; height: 22%; left: 52%; top: 30%;
  background: rgba(0,0,0,0.16);
  box-shadow: -10px 9px 0 rgba(255,255,255,0.12);
}

.mc-line { display: block; white-space: nowrap; }
.mc-word { display: inline-block; white-space: nowrap; }
.mc-word + .mc-word { margin-left: 0.3em; }
.mc-ch { display: inline-block; }
