/* Shared helpers for the channel motion templates. Deterministic: no clocks, seeded RNG only.
   Loaded synchronously before each template's template.js. */
(function () {
  "use strict";
  var MC = {};

  MC.root = function () { return document.querySelector("[data-composition-id]"); };

  /* Resolved variables: runtime values when available, otherwise declared defaults. */
  MC.vars = function () {
    var out = {};
    try {
      var decl = JSON.parse(document.documentElement.getAttribute("data-composition-variables") || "[]");
      decl.forEach(function (d) { out[d.id] = d["default"]; });
    } catch (e) { /* ignore */ }
    try {
      if (window.__hyperframes && typeof window.__hyperframes.getVariables === "function") {
        var v = window.__hyperframes.getVariables() || {};
        Object.keys(v).forEach(function (k) { if (v[k] !== undefined && v[k] !== null) out[k] = v[k]; });
      }
    } catch (e) { /* ignore */ }
    return out;
  };

  MC.bool = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };
  MC.num = function (v, d) { var n = parseFloat(v); return isFinite(n) ? n : d; };

  MC.dims = function (root) {
    var w = +root.getAttribute("data-width"), h = +root.getAttribute("data-height");
    return { w: w, h: h, vertical: h > w, duration: +root.getAttribute("data-duration") };
  };

  /* Common setup: orientation class, opaque mode, brand colour vars on the root. */
  MC.setup = function () {
    var root = MC.root();
    var d = MC.dims(root);
    var v = MC.vars();
    root.classList.add("mc-root", d.vertical ? "mc-v" : "mc-l");
    if (MC.bool(v.opaque)) root.classList.add("mc-opaque");
    return { root: root, d: d, v: v, id: root.getAttribute("data-composition-id") };
  };

  /* template.js calls MC.define(function (S) { ...; return tl; }); the generated index.html then
     registers window.__timelines[id] = MC.build() inline (synchronously, at page load). */
  MC.define = function (fn) { MC._def = fn; };
  MC.build = function () { return MC._def(MC.setup()); };

  /* mulberry32 seeded PRNG */
  MC.rng = function (seed) {
    var a = seed >>> 0;
    return function () {
      a = (a + 0x6d2b79f5) >>> 0;
      var t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  };

  /* Font-load-independent text fitting. Pixel fonts are near-monospace, so width ~= chars * size * k.
     Returns {lines: [string], size}. Never breaks inside a word. */
  MC.fit = function (text, o) {
    var k = o.k || 0.56, maxSize = o.maxSize, minSize = o.minSize || 8;
    var maxLines = o.maxLines || 2, lh = o.lineHeight || 1.05, maxH = o.maxHeight || 1e9;
    var words = String(text).trim().split(/\s+/).filter(Boolean);
    if (!words.length) return { lines: [""], size: maxSize };
    var best = null;
    function len(arr) { return arr.join(" ").length; }
    function partitions(ws, n) {
      if (n === 1) return [[ws]];
      var res = [];
      for (var i = 1; i <= ws.length - n + 1; i++) {
        partitions(ws.slice(i), n - 1).forEach(function (rest) { res.push([ws.slice(0, i)].concat(rest)); });
      }
      return res;
    }
    for (var n = 1; n <= Math.min(maxLines, words.length); n++) {
      var bestP = null, bestLen = 1e9;
      partitions(words, n).forEach(function (p) {
        var m = Math.max.apply(null, p.map(len));
        if (m < bestLen) { bestLen = m; bestP = p; }
      });
      var size = Math.min(maxSize, o.maxWidth / (bestLen * k), maxH / (n * lh));
      var score = size * Math.pow(0.8, n - 1); // prefer fewer lines unless it buys a lot of size
      if (!best || score > best.score) best = { lines: bestP.map(function (p) { return p.join(" "); }), size: size, score: score };
    }
    best.size = Math.max(minSize, Math.floor(best.size));
    return { lines: best.lines, size: best.size };
  };

  /* Render lines into el as .mc-line > .mc-word (> .mc-ch when chars=true).
     Words wrapped in *asterisks* get class "mc-hi". Returns {lines, words, chars}. */
  MC.renderLines = function (el, lines, opts) {
    opts = opts || {};
    el.textContent = "";
    var out = { lines: [], words: [], chars: [] };
    lines.forEach(function (line) {
      var ld = document.createElement("div");
      ld.className = "mc-line";
      line.split(" ").forEach(function (w, i, arr) {
        var hi = /^\*.*\*[^\w]*$/.test(w) || /^\*[^*]+\*$/.test(w);
        var clean = w.replace(/\*/g, "");
        var wd = document.createElement("span");
        wd.className = "mc-word" + (hi ? " mc-hi" : "");
        if (opts.chars) {
          Array.prototype.forEach.call(clean, function (c) {
            var cs = document.createElement("span");
            cs.className = "mc-ch";
            cs.textContent = c;
            wd.appendChild(cs);
            out.chars.push(cs);
          });
        } else {
          wd.textContent = clean;
        }
        ld.appendChild(wd);
        out.words.push(wd);
        // word gaps come from CSS margin (.mc-word + .mc-word): a text-node space collapses inside flex lines
      });
      el.appendChild(ld);
      out.lines.push(ld);
    });
    return out;
  };

  /* Text length ignoring highlight markers */
  MC.plain = function (t) { return String(t).replace(/\*/g, ""); };

  /* Colour helpers */
  function hexToRgb(h) {
    h = String(h).trim().replace("#", "");
    if (h.length === 3) h = h.split("").map(function (c) { return c + c; }).join("");
    var n = parseInt(h, 16);
    if (!isFinite(n)) n = 0xffcc33;
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  function rgbToHex(r) {
    return "#" + r.map(function (x) { return ("0" + Math.round(Math.max(0, Math.min(255, x))).toString(16)).slice(-2); }).join("");
