MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  /* Minecraft text shadow: offset by one font pixel (size / 8), colour = colour >> 2. */
  function mcShadow(el, size, color) {
    var o = Math.max(1, Math.round(size / 8));
    el.style.textShadow = o + "px " + o + "px 0 " + MC.shade(color, -0.75);
  }
  /* Snap to 4px steps on the logical canvas = whole font pixels once supersampled x2. */
  function snap(x) { return Math.max(8, Math.floor(x / 4) * 4); }
  var K = 0.75; // Minecraft font advance ~6/8 em for most glyphs

  var title = String(v.title == null ? "" : v.title).trim();
  var sub = String(v.subtitle == null ? "" : v.subtitle).trim();
  var color = String(v.color || "#FFCC33"), subColor = String(v.subtitle_color || "#FFFFFF");
  var tEl = document.getElementById("mt-title"), sEl = document.getElementById("mt-sub");
  if (MC.bool(v.bold)) tEl.className = "f-ui-bold mt-text";

  var fitT = MC.fit(title || " ", d.vertical
    ? { maxWidth: W * 0.88, maxSize: 72, minSize: 24, k: K, maxLines: 3, lineHeight: 1.15, maxHeight: H * 0.3 }
    : { maxWidth: W * 0.86, maxSize: 88, minSize: 24, k: K, maxLines: 2, lineHeight: 1.15, maxHeight: H * 0.42 });
  var tSize = snap(fitT.size);
  var fitS = MC.fit(sub || " ", d.vertical
    ? { maxWidth: W * 0.88, maxSize: 32, minSize: 16, k: K, maxLines: 2, lineHeight: 1.2 }
    : { maxWidth: W * 0.8, maxSize: 40, minSize: 16, k: K, maxLines: 2, lineHeight: 1.2 });
  var sSize = snap(Math.min(fitS.size, tSize * 0.55));

  function fill(el, lines, size, col, lh) {
    el.textContent = "";
    lines.forEach(function (ln) {
      var r = document.createElement("div");
      r.className = "mt-row"; r.textContent = ln; r.style.height = Math.round(size * lh) + "px";
      el.appendChild(r);
    });
    el.style.fontSize = size + "px"; el.style.color = col;
    mcShadow(el, size, col);
    return lines.length * Math.round(size * lh);
  }
  var tH = fill(tEl, fitT.lines, tSize, color, 1.15);
  var sH = sub ? fill(sEl, fitS.lines, sSize, subColor, 1.2) : 0;
  if (!sub) sEl.style.display = "none";
  var gap = sub ? Math.round(tSize * 0.35) : 0;
  // MC centres the title slightly above the middle of the screen
  var cy = H * (d.vertical ? 0.42 : 0.44);
  var top = Math.round(cy - (tH + gap + sH) / 2);
  tEl.style.top = top + "px";
  sEl.style.top = (top + tH + gap) + "px";

  var tl = gsap.timeline({ paused: true });
  var D = d.duration, IN = 0.35, OUT = 0.6;
  // vanilla /title is a pure alpha fade (fadeIn/stay/fadeOut); a tiny settle keeps it alive on video
  tl.fromTo(tEl, { opacity: 0, scale: 1.12 }, { opacity: 1, scale: 1, duration: IN, ease: "power2.out" }, 0);
  if (sub) tl.fromTo(sEl, { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: IN, ease: "power2.out" }, 0.12);
  tl.fromTo("#mt-wrap", { scale: 1 }, { scale: 1.025, duration: D - IN - OUT, ease: "none" }, IN);
  tl.to([tEl, sEl], { opacity: 0, duration: OUT, ease: "power1.in" }, D - OUT);
  return tl;
});
EOF
