    icon.innerHTML = MC.pixelSVG([
      "................",
      "................",
      "...OOOOOOOOOO...",
      "..OWWLLWWLLLLO..",
      ".OWLLWLLLWLLLDO.",
      "OWLLLLWLLLWLLLDO",
      "ODDDDDDDDDDDDDDO",
      ".OLMLLLLLLLLLDO.",
      "..OLMLLLLLLLDO..",
      "...OLMLLLLLDO...",
      "....OLMLLLDO....",
      ".....OLMLDO.....",
      "......OLDO......",
      ".......OO.......",
      "................",
      "................"
    ], { O: "#0c2f2c", W: "#e8fffd", L: "#4fe0d6", M: "#a8f4ee", D: "#1f9e95" }, 1);
  }

  var headEl = document.getElementById("at-head"), nameEl = document.getElementById("at-name"), descEl = document.getElementById("at-desc");
  mcText(headEl, head, fsT, K0.color);
  mcText(nameEl, name, fsT, "#FFFFFF");
  var ty = desc ? 6 * p : 7 * p;
  headEl.style.left = nameEl.style.left = descEl.style.left = textX + "px";
  headEl.style.top = ty + "px";
  nameEl.style.top = (ty + 11 * p) + "px";
  if (desc) { mcText(descEl, desc, fsT * 0.9, "#A8A8A8"); descEl.style.top = (ty + 22 * p) + "px"; }
  else descEl.style.display = "none";

  // challenge: a few pixel sparkles around the icon
  var sparks = [];
  if (kind === "challenge") {
    var wrap = document.getElementById("at-sparks");
    for (var i = 0; i < 8; i++) {
      var s = document.createElement("div");
      s.className = "at-spark";
      var sz = p * (rnd() < 0.5 ? 1 : 2);
      s.style.width = sz + "px"; s.style.height = sz + "px";
      s.style.background = i % 2 ? "#FF55FF" : "#FFFF55";
      s.style.left = (16 * p) + "px"; s.style.top = (th / 2) + "px";
      wrap.appendChild(s);
      var a = (i / 8) * Math.PI * 2 + rnd() * 0.5;
      sparks.push({ el: s, x: Math.cos(a) * p * (12 + rnd() * 8), y: Math.sin(a) * p * (10 + rnd() * 6) });
    }
