  tl.fromTo(toast, { x: offX }, { x: 0, duration: 0.42, ease: "power3.out" }, 0);
  tl.fromTo(slot, { scale: 0.4, rotation: -20 }, { scale: 1, rotation: 0, duration: 0.32, ease: "back.out(3)" }, 0.26);
