      for (var k in ADV) if (ADV[k].indexOf(c) >= 0) { a = +k; break; }
      w += a;
    }
    return w * size / 10;
  }

  // vanilla boss bar colours (approximate texture mid-tones)
  var COLORS = { pink: "#EC3FBF", blue: "#2FB5F0", red: "#F0402A", green: "#4CEC2B",
                 yellow: "#ECDF2B", purple: "#9A33EC", white: "#E6E6E6" };
  var cname = String(v.color || "pink").trim().toLowerCase();
  var col = COLORS[cname] || (/^#?[0-9a-f]{3,6}$/i.test(cname) ? (cname[0] === "#" ? cname : "#" + cname) : COLORS.pink);
  var from = clamp01(MC.num(v.from, 100) / 100), to = clamp01(MC.num(v.to, 35) / 100);
  var name = String(v.name == null ? "" : v.name);
  var notches = Math.round(MC.num(v.notches, 0));
  var hits = Math.max(1, Math.min(6, Math.round(MC.num(v.hits, 3))));

  var p = d.vertical ? 2.5 : 3;               // GUI pixel on the logical canvas
  var bw = 182 * p, bh = 5 * p, fs = 10 * p;  // name at 1 font px per gui px
  var nameW = mcWidth(name, fs);
  if (nameW > W * 0.92) { fs = fs * (W * 0.92) / nameW; }
  var top = d.vertical ? Math.round(H * 0.1) : 18;

  var wrap = document.getElementById("bb-wrap");
  wrap.style.width = W + "px"; wrap.style.top = top + "px"; wrap.style.height = (fs + 4 * p + bh) + "px";
  var nameEl = document.getElementById("bb-name");
  mcText(nameEl, name, fs, "#FFFFFF");
  nameEl.style.top = "0px";
  var bar = document.getElementById("bb-bar");
  bar.style.width = bw + "px"; bar.style.height = bh + "px";
  bar.style.left = Math.round((W - bw) / 2) + "px"; bar.style.top = (fs + 3 * p) + "px";
  // thin dark keyline so the bar reads over bright footage
  bar.style.boxShadow = "0 0 0 " + (p * 0.5) + "px rgba(0,0,0,0.55)";

  // pixel-art rows: 1px highlight, 3px body, 1px shade (vanilla bar texture structure)
  function rows(c) {
    var hi = MC.shade(c, 0.35), lo = MC.shade(c, -0.35);
    return "linear-gradient(to bottom, " + hi + " 0, " + hi + " " + p + "px, " + c + " " + p + "px, " + c + " " + (4 * p) + "px, " + lo + " " + (4 * p) + "px, " + lo + " 100%)";
  }
  var empty = MC.shade(col, -0.68);
  document.getElementById("bb-empty").style.background = rows(empty);
  document.getElementById("bb-fill").style.background = rows(col);
  document.getElementById("bb-lag").style.background = rows(MC.shade(col, 0.6));
  if (notches > 1) {
    var seg = bw / notches;
    document.getElementById("bb-notch").style.background =
      "repeating-linear-gradient(to right, transparent 0, transparent " + (seg - p) + "px, rgba(0,0,0,0.55) " + (seg - p) + "px, rgba(0,0,0,0.55) " + seg + "px)";
    document.getElementById("bb-notch").style.clipPath = "inset(" + p + "px 0 " + p + "px 0)";
  }

  var tl = gsap.timeline({ paused: true });
  var D = d.duration, fill = "#bb-fill", lag = "#bb-lag", flash = "#bb-flash";
  tl.fromTo(wrap, { y: -(top + 60), opacity: 0 }, { y: 0, opacity: 1, duration: 0.4, ease: "power3.out" }, 0);
  tl.set([fill, lag], { scaleX: from }, 0);
  tl.set(flash, { scaleX: from, opacity: 0 }, 0);

  if (to < from) {
    // drain in hits: the fill snaps down, a pale damage trail lingers then catches up
    var T0 = 0.65, span = D - 0.45 - T0 - 0.5, gap = hits > 1 ? span / (hits - 1) : 0;
    var weights = [], sum = 0;
    for (var i = 0; i < hits; i++) { var w = 1 + 0.35 * ((i * 7) % 3); weights.push(w); sum += w; }
    var cur = from;
    for (var j = 0; j < hits; j++) {
      var t = T0 + j * gap, next = cur - (from - to) * weights[j] / sum;
      if (j === hits - 1) next = to;
      tl.to(fill, { scaleX: next, duration: 0.05, ease: "none" }, t);
      tl.fromTo(flash, { scaleX: cur, opacity: 0.9 }, { scaleX: cur, opacity: 0, duration: 0.18, ease: "power1.out", immediateRender: false }, t);
      tl.to(lag, { scaleX: next, duration: 0.3, ease: "power2.inOut" }, t + 0.22);
      tl.fromTo(bar, { x: 0 }, { keyframes: [{ x: -2 * p }, { x: 2 * p }, { x: -p }, { x: 0 }], duration: 0.16, ease: "none", immediateRender: false }, t);
      tl.fromTo(nameEl, { y: 0 }, { keyframes: [{ y: -p }, { y: 0 }], duration: 0.12, ease: "none", immediateRender: false }, t);
      cur = next;
    }
  } else if (to > from) {
    tl.to([fill, lag], { scaleX: to, duration: 1.2, ease: "power1.inOut" }, 0.65);
    tl.fromTo(flash, { scaleX: to, opacity: 0 }, { keyframes: [{ opacity: 0.6 }, { opacity: 0 }], duration: 0.3, ease: "none", immediateRender: false }, 1.85);
  }
  tl.to(wrap, { y: -(top + 60), opacity: 0, duration: 0.35, ease: "power2.in" }, D - 0.38);
  return tl;
});

