MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(30);
  var GREEN = "#80FF20";

  var lf = Math.round(MC.num(v.level_from, 29)), lt = Math.round(MC.num(v.level_to, 30));
  if (lt <= lf) lf = lt - 1;
  var N = lt - lf;

  var p = d.vertical ? 2.5 : 3;              // GUI pixel on the logical canvas
  var bw = 182 * p, bh = 5 * p;
  var fs = d.vertical ? 50 : 60;             // level number: whole device pixels per font pixel
  var fp = fs / 10;
  var cy = Math.round(H * (d.vertical ? 0.6 : 0.7));
  var bx = Math.round((W - bw) / 2);

  var wrap = document.getElementById("xp-wrap");
  wrap.style.width = W + "px"; wrap.style.height = H + "px";
  var bar = document.getElementById("xp-bar");
  bar.style.left = bx + "px"; bar.style.top = cy + "px"; bar.style.width = bw + "px"; bar.style.height = bh + "px";
  // vanilla XP bar: black frame, dark interior, bright green fill with a light top row
  bar.style.boxShadow = "inset 0 0 0 " + p + "px #000, inset 0 0 0 " + (bh) + "px #23331a";
  var fill = document.getElementById("xp-fill");
  fill.style.left = p + "px"; fill.style.top = p + "px";
  fill.style.width = (bw - 2 * p) + "px"; fill.style.height = (bh - 2 * p) + "px";
  fill.style.background = "linear-gradient(to bottom, #c8ff7a 0, #c8ff7a " + p + "px, " + GREEN + " " + p + "px, " + GREEN + " " + (2 * p) + "px, #4fae12 " + (2 * p) + "px, #4fae12 100%)";
  var flash = document.getElementById("xp-flash");
  flash.style.left = p + "px"; flash.style.top = p + "px";
  flash.style.width = (bw - 2 * p) + "px"; flash.style.height = (bh - 2 * p) + "px";

  var num = document.getElementById("xp-num");
  num.style.fontSize = fs + "px";
  num.style.top = (cy - fs - 2 * p) + "px";
  num.style.height = fs + "px";
  // vanilla draws the level 4x in black at +-1 font px, then green on top
  num.style.textShadow = fp + "px 0 0 #000, -" + fp + "px 0 0 #000, 0 " + fp + "px 0 #000, 0 -" + fp + "px 0 #000";
  num.style.transformOrigin = "50% 80%";
  num.textContent = String(lf);

  // XP orbs (8x8 vanilla-ish sprite)
  var orbSVG = MC.pixelSVG([
    "..OOOO..",
    ".OYGGYO.",
    "OYWGGGYO",
    "OGGGGGGO",
    "OGGGGGGO",
    "OYGGGGYO",
    ".OYGGYO.",
    "..OOOO.."
  ], { O: "#2f6b05", Y: "#e9ff57", G: "#93ff2e", W: "#ffffff" }, 1);
  var orbs = [];
  if (MC.bool(v.orbs)) {
    var ow = document.getElementById("xp-orbs");
    for (var i = 0; i < 10; i++) {
      var o = document.createElement("div");
      o.className = "xp-orb";
      var sz = Math.round(8 * p * (0.8 + rnd() * 0.5));
      o.style.width = sz + "px"; o.style.height = sz + "px";
      o.innerHTML = orbSVG;
      ow.appendChild(o);
      var tx = bx + bw * (0.15 + 0.7 * rnd()) - sz / 2, ty = cy + bh / 2 - sz / 2;
      var sx = bx + bw * (-0.05 + 1.1 * rnd()) - sz / 2, sy = cy + (d.vertical ? 90 : 70) + rnd() * (d.vertical ? 140 : 90);
      orbs.push({ el: o, sx: sx, sy: sy, tx: tx, ty: ty });
    }
  }

  // pixel sparkle burst around the number on the final level
  var sparks = [], sw = document.getElementById("xp-sparks");
  for (var k = 0; k < 12; k++) {
    var s = document.createElement("div");
    s.className = "xp-spark";
    var ss = p * (k % 3 === 0 ? 2 : 1.5);
    s.style.width = ss + "px"; s.style.height = ss + "px";
    s.style.background = k % 2 ? GREEN : "#e9ff57";
    s.style.boxShadow = "0 0 0 " + (p * 0.5) + "px rgba(0,0,0,0.6)";
    sw.appendChild(s);
    var a = (k / 12) * Math.PI * 2 + rnd() * 0.4, r = fs * (0.9 + rnd() * 0.6);
    sparks.push({ el: s, x0: W / 2 - ss / 2, y0: cy - fs * 0.6, x: Math.cos(a) * r * 1.3, y: Math.sin(a) * r * 0.8 });
  }

  var tl = gsap.timeline({ paused: true });
  var D = d.duration;
  tl.fromTo(wrap, { opacity: 0, y: 3 * p }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out" }, 0);
  tl.set(fill, { scaleX: 0 }, 0);

  orbs.forEach(function (o, i) {
    var t = 0.12 + i * 0.09;
    tl.fromTo(o.el, { x: o.sx, y: o.sy, opacity: 0, scale: 0.6 },
      { x: o.tx, opacity: 1, scale: 1, duration: 0.42, ease: "power1.inOut", immediateRender: true }, t);
    tl.fromTo(o.el, { y: o.sy }, { y: o.ty, duration: 0.42, ease: "back.in(1.6)", immediateRender: false }, t);
    tl.to(o.el, { scale: 0, opacity: 0, duration: 0.08, ease: "power1.in" }, t + 0.42);
  });

  // fill: progress q goes 0 -> N + 0.2 (rolls over each level); bar and number are pure functions of q
  var F0 = 0.3, FD = 1.15, END = N + 0.2;
  var proxy = { q: 0 };
  function frac(q) { var f = q - Math.floor(q); return (q >= END - 1e-6) ? (END - Math.floor(END)) : f; }
  tl.fromTo(proxy, { q: 0 }, {
    q: END, duration: FD, ease: "power1.in",
    onUpdate: function () {
      var q = proxy.q;
      gsap.set(fill, { scaleX: frac(q) });
      num.textContent = String(lf + Math.min(N, Math.floor(q + 1e-6)));
    }
  }, F0);
  // level crossings: with power1.in, q(t) = END * u^2 -> u_k = sqrt(k / END)
  var pops = N <= 10 ? N : 1;
  for (var j = 1; j <= N; j++) {
    if (pops === 1 && j < N) continue;
    var tk = F0 + FD * Math.sqrt(j / END), last = j === N;
    tl.fromTo(num, { scale: last ? 1.7 : 1.3 }, { scale: 1, duration: last ? 0.4 : 0.18, ease: last ? "back.out(2.6)" : "power2.out", immediateRender: false }, tk);
    tl.fromTo(flash, { scaleX: 1, opacity: last ? 0.85 : 0.45 }, { scaleX: 1, opacity: 0, duration: 0.2, ease: "power1.out", immediateRender: false }, tk);
    if (last) {
      sparks.forEach(function (s) {
        tl.fromTo(s.el, { x: s.x0, y: s.y0, opacity: 0, scale: 1 },
          { keyframes: [{ opacity: 1, duration: 0.01 }, { x: s.x0 + s.x, y: s.y0 + s.y, opacity: 0, scale: 0.4, duration: 0.55, ease: "power2.out" }], immediateRender: true }, tk);
      });
      tl.fromTo(bar, { y: 0 }, { keyframes: [{ y: p }, { y: 0 }], duration: 0.14, ease: "none", immediateRender: false }, tk);
    }
  }
  tl.to(wrap, { opacity: 0, y: -3 * p, duration: 0.28, ease: "power2.in" }, D - 0.3);
  return tl;
});

