MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  /* Minecraft Regular / Bold advance tables (font px; 1 font px = size/10). */
  var ADV = { 2: "!,.:;i|", 3: "'l", 4: " I[]t", 5: "\"()*<>fk{}", 7: "@~" };
  var ADVB = { 3: "!,.:;i|", 4: " 'l", 5: "I[]t", 6: "\"()*<>fk{}", 8: "@~" };
  function adv(c, bold) {
    var tab = bold ? ADVB : ADV;
    for (var k in tab) if (tab[k].indexOf(c) >= 0) return +k;
    return bold ? 7 : 6;
  }
  function segWidth(t, bold, size) { var w = 0; for (var i = 0; i < t.length; i++) w += adv(t.charAt(i), bold); return w * size / 10; }

  var CODES = { "0": "#000000", "1": "#0000AA", "2": "#00AA00", "3": "#00AAAA", "4": "#AA0000", "5": "#AA00AA",
                "6": "#FFAA00", "7": "#AAAAAA", "8": "#555555", "9": "#5555FF", a: "#55FF55", b: "#55FFFF",
                c: "#FF5555", d: "#FF55FF", e: "#FFFF55", f: "#FFFFFF" };
  // "<Name> msg" -> player chat (white); anything else -> system message (yellow). &x / §x colour codes.
  function parse(line) {
    var base = /^\s*</.test(line) ? "#FFFFFF" : "#FFFF55";
    var segs = [], col = base, bold = false, buf = "";
    for (var i = 0; i < line.length; i++) {
      var c = line.charAt(i), n = line.charAt(i + 1).toLowerCase();
      if ((c === "§" || c === "&") && /[0-9a-fklmnor]/.test(n) && n) {
        if (buf) { segs.push({ t: buf, c: col, b: bold }); buf = ""; }
        if (CODES[n]) { col = CODES[n]; bold = false; }
        else if (n === "l") bold = true;
        else if (n === "r") { col = base; bold = false; }
        i++; continue;
      }
      buf += c;
    }
    if (buf) segs.push({ t: buf, c: col, b: bold });
    return segs;
  }
  // word-wrap a list of segments to maxW, keeping colours (vanilla wraps long chat lines)
  function wrap(segs, size, maxW) {
    var words = [];
    segs.forEach(function (s) {
      s.t.split(/( )/).forEach(function (w) { if (w) words.push({ t: w, c: s.c, b: s.b }); });
    });
    var rows = [[]], x = 0;
    words.forEach(function (w) {
      var ww = segWidth(w.t, w.b, size);
      if (w.t === " " && x === 0) return;
      if (x + ww > maxW && x > 0 && w.t !== " ") { rows.push([]); x = 0; }
      rows[rows.length - 1].push(w); x += ww;
    });
    return rows.map(function (r) {
      while (r.length && r[r.length - 1].t === " ") r.pop();
      return r;
    });
  }
  function rowWidth(r, size) { return r.reduce(function (a, w) { return a + segWidth(w.t, w.b, size); }, 0); }

  var raw = String(v.lines == null ? "" : v.lines).split("|").map(function (s) { return s.trim(); }).filter(Boolean);
  if (!raw.length) raw = [" "];
  raw = raw.slice(-10);

  var p = d.vertical ? 2.5 : 2;          // GUI pixel on the logical canvas
  var fs = 10 * p, LH = 9 * p, pad = 2 * p;
  var maxText = (d.vertical ? W - 32 : Math.min(320 * p, W * 0.62)) - 2 * pad;
  var msgs = raw.map(function (ln) { return wrap(parse(ln), fs, maxText); });
  var widest = 0;
  msgs.forEach(function (rows) { rows.forEach(function (r) { widest = Math.max(widest, rowWidth(r, fs)); }); });
  var cw = Math.round(Math.max(160 * p, widest + 2 * pad + p));

  var chat = document.getElementById("cm-chat");
  var left = d.vertical ? 16 : 10;
  var bottom = Math.round(d.vertical ? H * 0.74 : H - 56);   // vertical: above the Shorts caption/UI zone
  chat.style.left = left + "px"; chat.style.top = "0px"; chat.style.width = cw + "px"; chat.style.height = H + "px";

  var els = [], heights = [];
  msgs.forEach(function (rows) {
    var m = document.createElement("div");
    m.className = "cm-msg f-ui";
    var h = rows.length * LH;
    m.style.top = (bottom - h) + "px"; m.style.width = cw + "px";
    rows.forEach(function (r) {
      var row = document.createElement("div");
      row.className = "cm-row";
      row.style.height = LH + "px"; row.style.width = cw + "px";
      row.style.paddingLeft = pad + "px"; row.style.paddingTop = (p * 0.5) + "px";
      row.style.fontSize = fs + "px";
      r.forEach(function (w) {
        var sp = document.createElement("span");
        sp.textContent = w.t; sp.style.color = w.c;
        if (w.b) sp.className = "cm-b";
        sp.style.textShadow = (fs / 10) + "px " + (fs / 10) + "px 0 " + MC.shade(w.c, -0.75);
        row.appendChild(sp);
      });
      m.appendChild(row);
    });
    chat.appendChild(m);
    els.push(m); heights.push(h);
  });

  var tl = gsap.timeline({ paused: true });
  var D = d.duration, n = els.length;
  var gap = Math.min(0.55, 2.1 / Math.max(1, n)), T0 = 0.15;
  var times = els.map(function (_, i) { return T0 + i * gap; });
  els.forEach(function (m, i) {
    tl.fromTo(m, { opacity: 0, x: -6 * p }, { opacity: 1, x: 0, duration: 0.14, ease: "power2.out" }, times[i]);
    // pushed up by every later message
    var cum = 0;
    for (var j = i + 1; j < n; j++) {
      var prev = cum; cum += heights[j];
      tl.fromTo(m, { y: -prev }, { y: -cum, duration: 0.1, ease: "power2.out", immediateRender: false }, times[j]);
    }
  });
  // vanilla-style fade: oldest lines go first
  var FO = Math.max(times[n - 1] + 0.7, D - 0.85);
  els.forEach(function (m, i) {
    tl.to(m, { opacity: 0, duration: 0.35, ease: "power1.in" }, Math.min(FO + i * 0.08, D - 0.36));
  });
  return tl;
});

