MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var ADV = { 2: "!,.:;i|", 3: "'l", 4: " I[]t", 5: "\"()*<>fk{}", 7: "@~" };
  function mcWidth(t, size) {
    var w = 0;
    for (var i = 0; i < t.length; i++) {
      var c = t.charAt(i), a = 6;
      for (var k in ADV) if (ADV[k].indexOf(c) >= 0) { a = +k; break; }
      w += a;
    }
    return w * size / 10;
  }
  function clampSlot(x, dflt) { var n = Math.round(MC.num(x, dflt)); return Math.max(1, Math.min(9, n)) - 1; }

  /* 16x16 item sprites (vanilla-inspired) */
  var DIA = { O: "#0c2f2c", W: "#e8fffd", L: "#4fe0d6", M: "#a8f4ee", D: "#1f9e95" };
  var SPR = {
    sword: [["..............OO",".............OWO","............OWLO","...........OWLO.","..........OWLO..",".........OWLO...","........OWLO....",".OO....OWLO.....",".OGO..OWLO......","..OGOOWLO.......","...OGOLO........","....OGOO........","...OBOGGO.......","..OBO..OO.......",".OBO............","OO.............."],
            { O: "#0c2f2c", W: "#e8fffd", L: "#4fe0d6", G: "#1f9e95", B: "#6b4a26" }],
    pickaxe: [["................","...OOOOOO.......","..OWLLLLLOO.....","...OOOOOOLLO....","........OBOLO...",".......OBO.OLO..","......OBO..OLLO.",".....OBO....OLO.","....OBO.....OLO.","...OBO.......OO.","..OBO...........",".OBO............","OBO.............","OO..............","................","................"],
              { O: "#0c2f2c", W: "#e8fffd", L: "#4fe0d6", B: "#6b4a26" }],
    torch: [["................","................",".......OO.......","......OYYO......","......OYWO......","......OYYO......","......OBBO......","......OBBO......","......OBDO......","......OBDO......","......OBDO......","......OBDO......","......OBDO......","......OBDO......",".......OO.......","................"],
            { O: "#2a1a0a", Y: "#ffd23f", W: "#fff7c2", B: "#8a6234", D: "#5b3d1c" }],
    apple: [["................","........O.GG....",".......OBGGGG...","....OOOOBOOO....","...ORRRRRRRRO...","..ORWRRRRRRRRO..","..ORWRRRRRRRRO..","..ORRRRRRRRRDO..","..ORRRRRRRRRDO..","..ORRRRRRRRDDO..","...ORRRRRRRDO...","....ORRDDRDO....",".....OO..OO.....","................","................","................"],
            { O: "#2b0606", R: "#e0262a", W: "#ffb3b3", D: "#9a1418", B: "#5b3d1c", G: "#3fae2a" }],
    bread: [["................","................","................","................","......OOOOO.....","....OOLLLLLOO...","...OLLYLLYLLLO..","..OLYLLYLLYLLLO.",".OLLLLLLLLLLLDO.",".ODLLLLLLLLLDDO.","..ODDDDDDDDDDO..","...OOOOOOOOOO...","................","................","................","................"],
            { O: "#3a2208", L: "#c98b3c", Y: "#f0c27a", D: "#8a5a22" }],
    diamond: [["................","................","...OOOOOOOOOO...","..OWWLLWWLLLLO..",".OWLLWLLLWLLLDO.","OWLLLLWLLLWLLLDO","ODDDDDDDDDDDDDDO",".OLMLLLLLLLLLDO.","..OLMLLLLLLLDO..","...OLMLLLLLDO...","....OLMLLLDO....",".....OLMLDO.....","......OLDO......",".......OO.......","................","................"], DIA]
  };
  // procedural block faces (seeded, so deterministic)
  function blockRows(kind) {
    var r = MC.rng(kind === "grass" ? 11 : 23), rows = [];
    for (var y = 0; y < 16; y++) {
      var row = "";
      for (var x = 0; x < 16; x++) {
        var n = r();
        if (x === 0 || y === 0 || x === 15 || y === 15) { row += "O"; continue; }
        if (kind === "grass") {
          var drip = y < 4 || (y < 6 && ((x * 7) % 5 < 2));
          row += drip ? (n < 0.3 ? "g" : "G") : (n < 0.25 ? "d" : (n < 0.35 ? "s" : "D"));
        } else {
          row += n < 0.22 ? "k" : (n < 0.45 ? "l" : (n < 0.55 ? "w" : "c"));
        }
      }
      rows.push(row);
    }
    return rows;
  }
  SPR.grass = [blockRows("grass"), { O: "#1e1408", G: "#5fbf3a", g: "#4a9a2c", D: "#8a5a35", d: "#6b4426", s: "#a87a52" }];
